<ComponentPreview name="carousel-demo" previewClass="h-80 sm:h-[32rem]" />

## About

The Carousel component is built with [Embla Carousel](https://www.embla-carousel.com/), which provides motion, swipe, and keyboard navigation.

## Installation

<CodeTabs>

<TabsList variant="line" class="gap-6">
  <TabsTrigger value="cli">Command</TabsTrigger>
  <TabsTrigger value="manual">Manual</TabsTrigger>
</TabsList>

<TabsContent value="cli">

```package-dlx
shadcn@latest add @zaidan/carousel
```

</TabsContent>

<TabsContent value="manual">

<Steps class="mb-0 pt-2">

<Step>Install the following dependencies:</Step>

```package-install
embla-carousel embla-carousel-solid lucide-solid
```

<Step>Copy and paste the following code into your project.</Step>

<ComponentSource name="carousel" title="components/ui/carousel.tsx" />

<Step>Update the import paths to match your project setup.</Step>

</Steps>

</TabsContent>

</CodeTabs>

## Usage

```tsx showLineNumbers
import {
  Carousel,
  CarouselContent,
  CarouselItem,
  CarouselNext,
  CarouselPrevious,
} from "~/components/ui/carousel";
```

```tsx showLineNumbers
<Carousel>
  <CarouselContent>
    <CarouselItem>...</CarouselItem>
    <CarouselItem>...</CarouselItem>
    <CarouselItem>...</CarouselItem>
  </CarouselContent>
  <CarouselPrevious />
  <CarouselNext />
</Carousel>
```

## Composition

Use the following composition to build a `Carousel`:

```text
Carousel
├── CarouselContent
│   ├── CarouselItem
│   └── CarouselItem
├── CarouselPrevious
└── CarouselNext
```

## Sizes

To set the size of the items, use the `basis` utility class on `<CarouselItem />`.

<ComponentPreview name="carousel-size" />

```tsx showLineNumbers {4-6}
// 33% of the carousel width.
<Carousel>
  <CarouselContent>
    <CarouselItem class="basis-1/3">...</CarouselItem>
    <CarouselItem class="basis-1/3">...</CarouselItem>
    <CarouselItem class="basis-1/3">...</CarouselItem>
  </CarouselContent>
</Carousel>
```

```tsx showLineNumbers {4-6}
// 50% on small screens and 33% on larger screens.
<Carousel>
  <CarouselContent>
    <CarouselItem class="md:basis-1/2 lg:basis-1/3">...</CarouselItem>
    <CarouselItem class="md:basis-1/2 lg:basis-1/3">...</CarouselItem>
    <CarouselItem class="md:basis-1/2 lg:basis-1/3">...</CarouselItem>
  </CarouselContent>
</Carousel>
```

## Spacing

To set item spacing, use a `pl-[VALUE]` utility on `<CarouselItem />` and a negative `-ml-[VALUE]` on `<CarouselContent />`.

<ComponentPreview name="carousel-spacing" />

```tsx showLineNumbers /-ml-4/ /pl-4/
<Carousel>
  <CarouselContent class="-ml-4">
    <CarouselItem class="pl-4">...</CarouselItem>
    <CarouselItem class="pl-4">...</CarouselItem>
    <CarouselItem class="pl-4">...</CarouselItem>
  </CarouselContent>
</Carousel>
```

```tsx showLineNumbers /-ml-2/ /pl-2/ /md:-ml-4/ /md:pl-4/
<Carousel>
  <CarouselContent class="-ml-2 md:-ml-4">
    <CarouselItem class="pl-2 md:pl-4">...</CarouselItem>
    <CarouselItem class="pl-2 md:pl-4">...</CarouselItem>
    <CarouselItem class="pl-2 md:pl-4">...</CarouselItem>
  </CarouselContent>
</Carousel>
```

## Orientation

Use the `orientation` prop to set the carousel orientation.

<ComponentPreview name="carousel-orientation" previewClass="h-[32rem]" />

```tsx showLineNumbers /vertical | horizontal/
<Carousel orientation="vertical | horizontal">
  <CarouselContent>
    <CarouselItem>...</CarouselItem>
    <CarouselItem>...</CarouselItem>
    <CarouselItem>...</CarouselItem>
  </CarouselContent>
</Carousel>
```

## Options

Pass options to the carousel using the `opts` prop. See the [Embla Carousel options documentation](https://www.embla-carousel.com/api/options/) for more information.

```tsx showLineNumbers {2-5}
<Carousel
  opts={{
    align: "start",
    loop: true,
  }}
>
  <CarouselContent>
    <CarouselItem>...</CarouselItem>
    <CarouselItem>...</CarouselItem>
    <CarouselItem>...</CarouselItem>
  </CarouselContent>
</Carousel>
```

## API

Use a signal and the `setApi` prop to get an instance of the carousel API.

<ComponentPreview name="carousel-api" previewClass="sm:h-[32rem]" />

```tsx showLineNumbers {1,4,23}
import { createEffect, createSignal, onCleanup } from "solid-js";
import { type CarouselApi } from "~/components/ui/carousel";

export function Example() {
  const [api, setApi] = createSignal<CarouselApi>();
  const [current, setCurrent] = createSignal(0);
  const [count, setCount] = createSignal(0);

  createEffect(() => {
    const carouselApi = api();
    if (!carouselApi) return;

    const onSelect = () => {
      setCurrent(carouselApi.selectedScrollSnap() + 1);
    };

    setCount(carouselApi.scrollSnapList().length);
    onSelect();
    carouselApi.on("select", onSelect);
    onCleanup(() => carouselApi.off("select", onSelect));
  });

  return (
    <Carousel setApi={setApi}>
      <CarouselContent>
        <CarouselItem>...</CarouselItem>
        <CarouselItem>...</CarouselItem>
        <CarouselItem>...</CarouselItem>
      </CarouselContent>
    </Carousel>
  );
}
```

## Events

Listen to events using the API instance from `setApi`.

```tsx showLineNumbers {1,4-17,19}
import { createEffect, createSignal, onCleanup } from "solid-js";
import { type CarouselApi } from "~/components/ui/carousel";

export function Example() {
  const [api, setApi] = createSignal<CarouselApi>();

  createEffect(() => {
    const carouselApi = api();
    if (!carouselApi) return;

    const onSelect = () => {
      // Do something on select.
    };

    carouselApi.on("select", onSelect);
    onCleanup(() => carouselApi.off("select", onSelect));
  });

  return (
    <Carousel setApi={setApi}>
      <CarouselContent>
        <CarouselItem>...</CarouselItem>
        <CarouselItem>...</CarouselItem>
        <CarouselItem>...</CarouselItem>
      </CarouselContent>
    </Carousel>
  );
}
```

See the [Embla Carousel events documentation](https://www.embla-carousel.com/api/events/) for more information.

## Plugins

Use the `plugins` prop to add plugins to the carousel.

```ts showLineNumbers {1,6-10}
import Autoplay from "embla-carousel-autoplay";

export function Example() {
  return (
    <Carousel
      plugins={[
        Autoplay({
          delay: 2000,
        }),
      ]}
    >
      // ...
    </Carousel>
  );
}
```

<ComponentPreview name="carousel-plugin" previewClass="sm:h-[32rem]" />

## API Reference

See the [Embla Carousel API reference](https://www.embla-carousel.com/api/) for information on options, events, and plugins.

