  };

const InputGroupButton = (rawProps: InputGroupButtonProps) => {
  const props = mergeProps({ type: "button", variant: "ghost", size: "xs" } as const, rawProps);
  const [local, others] = splitProps(props, ["class", "type", "variant", "size"]);

  return (
